sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float mono;
uniform float freeze;
uniform float extremes;
uniform float2 offset;
uniform float overshoot;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 n = floor(coord - offset);
    float frame = freeze > 0.5 ? 0.0 : mod(floor(time * 60.0 + 0.001), 4096.0);
    float3 k = float3(n, frame);
    float3 v = float3(hash13(k), hash13(k + 19.7), hash13(k + 41.3));
    if (mono > 0.5) v = v.xxx;
    if (extremes > 0.5) v = step(0.5, v);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = clamp(base * mix(float3(1.0), v * overshoot, clamp(amount, 0.0, 1.0)), 0.0, 1.0);
    return half4(half3(rgb) * src.a, src.a);
}
